from typing import List
import math

def getMinDistSum(positions: List[List[int]]) -> float:
    def total(x, y):
        return sum(math.hypot(x - px, y - py) for px, py in positions)

    xs = [p[0] for p in positions]
    ys = [p[1] for p in positions]

    def best_for_x(x):
        # Ternary search on y (function is convex in y)
        lo, hi = min(ys), max(ys)
        for _ in range(60):
            m1 = lo + (hi - lo) / 3
            m2 = hi - (hi - lo) / 3
            if total(x, m1) < total(x, m2):
                hi = m2
            else:
                lo = m1
        return total(x, (lo + hi) / 2)

    # Ternary search on x (min over y of a convex function is convex)
    lo, hi = min(xs), max(xs)
    for _ in range(60):
        m1 = lo + (hi - lo) / 3
        m2 = hi - (hi - lo) / 3
        if best_for_x(m1) < best_for_x(m2):
            hi = m2
        else:
            lo = m1
    return best_for_x((lo + hi) / 2)
